/** Browser-only memory ports. These exercise the real application/engine, never SQL atomicity or live model quality. */
import {upgradeV05Package} from '@camery/ir';
import {WorkbenchCandidatePageSchema} from '@camery/ir/workbench';
import {createVersionState,submitChangeSet,adoptChangeSet,rejectChangeSet} from '@camery/versioning';
import type {StoredVersionState,VersionProjectKey,PersistedChangeResult,VersionTransactionReceipt} from '@camery/versioning/node';
import {VersionPersistenceError} from '@camery/versioning/node';
import {DevelopmentAdoptionSourceSchema,DevelopmentFormalIdentitiesSchema} from '@camery/script/node';
import type {DevelopmentStore} from '@camery/script/node';
import {makePackage} from '../../../ir/test/fixtures.js';
import {newProjectObjectId} from '../../src/projects/ids.js';
import {ProjectIdentityScopeSchema,PrincipalIdentityScopeSchema,ResolveProjectIdentitySchema} from '../../src/projects/contracts.js';
import {CandidateIntentKeySchema,CandidateChangeKeySchema,CandidateIntentBodySchema,DecisionIntentKeySchema,DecisionIntentBodySchema,ProjectApplicationError,ProjectActionReceiptSchema} from '../../src/projects/intent-contracts.js';
import type {CandidateIntent,DecisionIntent,ProjectActionReceipt} from '../../src/projects/intent-contracts.js';
import {projectIntentDigest} from '../../src/projects/intent-store.js';
import type {ProjectApplicationOptions} from '../../src/projects/options.js';

const copy=<T,>(value:T):T=>structuredClone(value);
export function createProjectBrowserState(store:DevelopmentStore){
  const ids=new Map<string,string>();const heads=new Map<string,StoredVersionState>();const candidates=new Map<string,CandidateIntent>();const decisions=new Map<string,DecisionIntent>();const preparation=new Map<string,ProjectActionReceipt>();const receipts=new Map<string,ProjectActionReceipt>();
  const key=(value:unknown)=>JSON.stringify(value);const allocate=(slot:unknown)=>{const name=key(slot);let value=ids.get(name);if(!value){value=newProjectObjectId();ids.set(name,value);}return value;};
  const target=(tenantId:string,projectId:string)=>({tenantId:allocate(['tenant',tenantId]),projectId:allocate(['project',tenantId,projectId])});
  const projectKey=(value:VersionProjectKey)=>key([value.tenantId,value.projectId]);
  function project(tenantId:string,projectId:string){const mapped=target(tenantId,projectId);const name=projectKey(mapped);if(!heads.has(name)){const baseline=upgradeV05Package(makePackage());for(const [collection,value] of Object.entries(baseline))if(Array.isArray(value))(baseline as unknown as Record<string,unknown>)[collection]=[];baseline.package_id=allocate(['package',tenantId,projectId]);baseline.project.id=mapped.projectId;baseline.project.source_ids=[];baseline.project.scope={label:'Browser protocol baseline',expected_episode_count:0,expected_scene_count:0,expected_required_beat_count:0};baseline.revision={number:1,status:'adopted',note:'Explicit browser fixture initialization'};heads.set(name,{state:createVersionState(baseline),writeVersion:1});}return {tenantId,projectId,versionKey:mapped};}
  const principal=(tenantId:string,kind:'user'|'agent_run'|'system',userKey:string)=>({tenantId,kind,key:userKey,principal:{kind,id:allocate(['principal',tenantId,kind,userKey])}});
  const candidateKey=(scope:{tenantId:string;projectId:string},applicationId:string)=>key([scope.tenantId,scope.projectId,applicationId]);
  const decisionKey=(scope:{tenantId:string;projectId:string},kind:string,actorKey:string,requestId:string)=>key([scope.tenantId,scope.projectId,kind,actorKey,requestId]);
  const read=(mapped:VersionProjectKey)=>{const found=heads.get(projectKey(mapped));if(!found)throw new ProjectApplicationError('NOT_FOUND','browser project');return found;};
  function check(mapped:VersionProjectKey,expected:{expectedSnapshotRevision:number;expectedWriteVersion:number}|undefined){const found=read(mapped);if(expected&&(found.state.head.revision.number!==expected.expectedSnapshotRevision||found.writeVersion!==expected.expectedWriteVersion))throw new VersionPersistenceError('WRITE_VERSION_CONFLICT','browser CAS',mapped.projectId);return found;}
  const receipt=(candidate:CandidateIntent,result:Readonly<PersistedChangeResult>)=>ProjectActionReceiptSchema.parse({version:1,changeId:candidate.changeId,status:result.status,snapshotRevision:result.state.head.revision.number,writeVersion:result.writeVersion,issues:result.issues,warnings:result.warnings,adoption:result.state.adoptions.find(value=>value.change_set_id===candidate.changeId)??null,rejection:result.state.changes.find(value=>value.request.id===candidate.changeId)?.rejection??null});
  const options:ProjectApplicationOptions={tenantId:'tenant',newId:newProjectObjectId,
    identities:{
      async resolveProject(input){const scope=ProjectIdentityScopeSchema.parse(input);return copy(project(scope.tenantId,scope.projectId));},
      async resolvePrincipal(input){const scope=PrincipalIdentityScopeSchema.parse(input);return copy(principal(scope.tenantId,scope.kind,scope.key));},
      async resolve(input){const scope=ResolveProjectIdentitySchema.parse(input);const binding=project(scope.tenantId,scope.projectId);return copy({scope:{tenantId:scope.tenantId,projectId:scope.projectId},versionKey:binding.versionKey,principal:principal(scope.tenantId,scope.kind,scope.key).principal});},
    },
    development:{store:{read:key=>store.read(key),isCurrent:key=>store.isCurrent(key),async readForAdoption(_client,input){const source=DevelopmentAdoptionSourceSchema.parse(input);const progress=await store.read(source);if(!await store.isCurrent(source)||progress.run.digest!==source.runDigest||progress.run.brief.digest!==source.briefDigest||progress.foundation.review?.status!=='reviewed'||progress.episodes.review?.status!=='reviewed'||progress.foundation.review.digest!==source.foundationReviewDigest||progress.episodes.review.digest!==source.episodesReviewDigest)throw new ProjectApplicationError('CONFLICT','browser source');return progress;}},identities:{async prepare(input){const command=input as {source:unknown;target:VersionProjectKey};const source=DevelopmentAdoptionSourceSchema.parse(command.source);const progress=await options.development.store.readForAdoption(null as never,source);const foundation=progress.foundation.review;if(foundation?.status!=='reviewed')throw new ProjectApplicationError('CONFLICT','browser source review');const owner=progress.run.origin?.foundation??{runId:source.runId,runDigest:source.runDigest};const slot=(kind:string,local:string)=>allocate(['local',source.tenantId,source.projectId,kind,local]);const identities=DevelopmentFormalIdentitiesSchema.parse({tenantId:source.tenantId,projectId:source.projectId,target:command.target,foundationOwner:owner,planId:slot('plan','project'),worldId:slot('world',owner.runId),characters:foundation.output.characters.map(row=>({localId:row.id,id:slot('character',owner.runId+':'+row.id)})),relationships:foundation.output.relationships.map(row=>({localId:row.id,id:slot('relationship',owner.runId+':'+row.id)})),episodes:Array.from({length:100},(_,index)=>({number:index+1,episodeId:slot('episode',String(index+1)),planId:slot('episode-plan',String(index+1))}))});return {identities,progress};}}},
    versions:{
      async read(mapped){return copy(read(mapped));},
      async submitWithReceipt(mapped,request,submitOptions,writer){const found=check(mapped,submitOptions.expectation);const result={...submitChangeSet(found.state,request,submitOptions),writeVersion:found.writeVersion+1};await writer(null as never,result,{operation:'submit',project:mapped,...(submitOptions.expectation?{expectation:submitOptions.expectation}:{}),requestSignature:JSON.stringify(request)});heads.set(projectKey(mapped),{state:result.state,writeVersion:result.writeVersion});return copy(result);},
      async adoptGuarded(mapped,changeId,adoptOptions,guard,writer){await guard(null as never);const found=check(mapped,adoptOptions.expectation);const result={...adoptChangeSet(found.state,changeId,{...adoptOptions,authorize:(actor,scope)=>adoptOptions.authorize(actor,mapped,scope)}),writeVersion:found.writeVersion+1};if(writer)await writer(null as never,result,{operation:'adopt',project:mapped,...(adoptOptions.expectation?{expectation:adoptOptions.expectation}:{}),changeId,actor:adoptOptions.actor,scope:adoptOptions.scope,at:adoptOptions.at,replayed:false});heads.set(projectKey(mapped),{state:result.state,writeVersion:result.writeVersion});return copy(result);},
      async rejectWithReceipt(mapped,changeId,rejectOptions,reason,writer){const found=check(mapped,rejectOptions.expectation);const result={...rejectChangeSet(found.state,changeId,{...rejectOptions,authorize:(actor,scope)=>rejectOptions.authorize(actor,mapped,scope)},reason),writeVersion:found.writeVersion+1};await writer(null as never,result,{operation:'reject',project:mapped,...(rejectOptions.expectation?{expectation:rejectOptions.expectation}:{}),changeId,actor:rejectOptions.actor,scope:rejectOptions.scope,at:rejectOptions.at,reason});heads.set(projectKey(mapped),{state:result.state,writeVersion:result.writeVersion});return copy(result);},
    },
    intents:{
      async findCandidate(input){const command=CandidateIntentKeySchema.parse(input);return copy(candidates.get(candidateKey(command.scope,command.applicationId))??null);},
      async candidateForChange(input){const command=CandidateChangeKeySchema.parse(input);return copy([...candidates.values()].find(row=>row.scope.tenantId===command.scope.tenantId&&row.scope.projectId===command.scope.projectId&&row.changeId===command.changeId)??null);},
      async putCandidate(input){const body=CandidateIntentBodySchema.parse(input);const name=candidateKey(body.scope,body.applicationId);const previous=candidates.get(name);if(previous){if(previous.commandDigest!==body.commandDigest)throw new ProjectApplicationError('CONFLICT','browser candidate identity');return copy(previous);}const saved={...body,digest:projectIntentDigest(body),businessDigest:projectIntentDigest(body),createdAt:new Date().toISOString()};candidates.set(name,saved);if(!body.request)preparation.set(name,{version:1,changeId:body.changeId,status:'unchanged',snapshotRevision:body.expectation.expectedSnapshotRevision,writeVersion:body.expectation.expectedWriteVersion,issues:[],warnings:[],adoption:null,rejection:null});return copy(saved);},
      async findDecision(input){const command=DecisionIntentKeySchema.parse(input);return copy(decisions.get(decisionKey(command.scope,command.actorKind,command.actorKey,command.requestId))??null);},
      async putDecision(input){const body=DecisionIntentBodySchema.parse(input);const name=decisionKey(body.scope,body.actor.kind,body.actor.key,body.requestId);const previous=decisions.get(name);if(previous){const {digest:_digest,businessDigest:_business,createdAt:_created,...old}=previous;if(projectIntentDigest({...old,at:null})!==projectIntentDigest({...body,at:null}))throw new ProjectApplicationError('CONFLICT','browser decision identity');return copy(previous);}const saved={...body,digest:projectIntentDigest(body),businessDigest:projectIntentDigest(body),createdAt:new Date().toISOString()};decisions.set(name,saved);return copy(saved);},
      async readPreparationReceipt(input){const command=CandidateIntentKeySchema.parse(input);return copy(preparation.get(candidateKey(command.scope,command.applicationId))??null);},
      async readDecisionReceipt(input){const command=DecisionIntentKeySchema.parse(input);return copy(receipts.get(decisionKey(command.scope,command.actorKind,command.actorKey,command.requestId))??null);},
      preparationReceiptWriter(candidate):VersionTransactionReceipt{return async(_client,result)=>{preparation.set(candidateKey(candidate.scope,candidate.applicationId),receipt(candidate,result));};},
      decisionReceiptWriter(decision,candidate):VersionTransactionReceipt{return async(_client,result)=>{receipts.set(decisionKey(decision.scope,decision.actor.kind,decision.actor.key,decision.requestId),receipt(candidate,result));};},
      async listCandidateHeaders(query){const found=read(query.target);const items=[...candidates.values()].filter(row=>row.scope.tenantId===query.scope.tenantId&&row.scope.projectId===query.scope.projectId&&(!query.runId||row.source.kind==='development'&&row.source.source.runId===query.runId||row.source.kind==='manual'&&row.request?.ops.length===1&&row.request.ops[0]?.op==='upgrade_schema')).reverse().slice(0,query.limit??20).map(row=>({contractVersion:1,projectKey:row.scope.projectId,candidateId:row.changeId,applicationId:row.applicationId,managed:true,status:found.state.changes.find(change=>change.request.id===row.changeId)?.status??preparation.get(candidateKey(row.scope,row.applicationId))?.status??'prepared',authorId:row.actor.id,authorKey:row.actor.key,createdAt:row.createdAt,baseRevision:row.expectation.expectedSnapshotRevision,source:row.source.kind==='development'?{kind:'development',runId:row.source.source.runId,state:'unchecked'}:{kind:'manual'}}));return WorkbenchCandidatePageSchema.parse({contractVersion:1,items,nextCursor:null});},
    },
  };
  // Projects and account bindings are explicitly installed when this browser-only fixture starts.
  const install=()=>{project('tenant','project');project('tenant','project-two');principal('tenant','user','browser-human');};install();
  return {options,reset(){ids.clear();heads.clear();candidates.clear();decisions.clear();preparation.clear();receipts.clear();install();},stats(){return {candidates:candidates.size,decisions:decisions.size,preparation:preparation.size,receipts:receipts.size,projects:[...heads.values()].map(value=>({revision:value.state.head.revision.number,writeVersion:value.writeVersion,episodes:value.state.head.episodes.length}))};}};
}
